def ref_search_documentation(workspace_id, query, source_id=None, language=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0188000" if __import__("os").path.isdir("./environment_mix/0188000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, workspace_id_used=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "ref_req_" + hashlib.sha256(f"{time.time()}:{os.getpid()}:{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "tool": "ref_search_documentation",
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _valid_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    try:
        if not _valid_id(r"^ref_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
        if not isinstance(query, str) or len(query.strip()) < 1:
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "query must be a non-empty string.")
        if source_id is not None and not _valid_id(r"^ref_src_[0-9A-HJKMNP-TV-Z]{10,}$", source_id):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "Invalid source_id format.")
        if status is not None and status not in ("active", "superseded", "deleted"):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "Invalid status filter.")
        if limit is None:
            limit = 20
        if not isinstance(limit, int) or limit < 1 or limit > 50:
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
        if sort is None:
            sort = "relevance"
        if sort not in ("relevance", "indexed_at_desc", "indexed_at_asc"):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "Invalid sort value.")
        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "cursor must be a string.")

        workspaces = _load("workspaces.json")
        if not any(isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") != "deleted" for w in workspaces):
            _log("NOT_FOUND", None, workspace_id)
            return _err("NOT_FOUND", "Workspace not found.")

        sources = _load("documentation_sources.json")
        if not isinstance(sources, list):
            sources = []
        active_sources = {}
        for s in sources:
            if not isinstance(s, dict):
                continue
            if s.get("workspace_id") != workspace_id:
                continue
            if s.get("status") != "active":
                continue
            active_sources[s.get("id")] = s

        # If no documentation sources exist for a workspace, return empty result set.
        if len([s for s in sources if isinstance(s, dict) and s.get("workspace_id") == workspace_id]) == 0:
            _log("OK", None, workspace_id)
            return {
                "object": "list",
                "data": [],
                "meta": {"total": 0, "has_more": False, "next_cursor": None}
            }

        # If a source_id is given, it must belong to workspace and exist; but results may still be empty.
        if source_id is not None:
            src_row = next((s for s in sources if isinstance(s, dict) and s.get("id") == source_id), None)
            if src_row is None or src_row.get("workspace_id") != workspace_id:
                _log("NOT_FOUND", None, workspace_id)
                return _err("NOT_FOUND", "Source not found in workspace.")
            # If source isn't active, business rule says search must use active parent sources; results empty.
            if src_row.get("status") != "active":
                _log("OK", None, workspace_id)
                return {"object": "list", "data": [], "meta": {"total": 0, "has_more": False, "next_cursor": None}}

        docs = _load("indexed_documents.json")
        if not isinstance(docs, list):
            docs = []

        q = query.strip().lower()
        q_terms = [t for t in re.split(r"\s+", q) if t]

        def _score(doc):
            title = (doc.get("title") or "").lower()
            text = (doc.get("content_text") or "").lower()
            sc = 0
            for t in q_terms:
                if not t:
                    continue
                if t in title:
                    sc += 10
                # crude count occurrences capped for stability
                sc += min(text.count(t), 20)
            return sc

        # Cursor format: base64url(json({"i": offset}))
        offset = 0
        if cursor:
            try:
                pad = "=" * ((4 - (len(cursor) % 4)) % 4)
                raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
                obj = json.loads(raw)
                if not isinstance(obj, dict) or "i" not in obj or not isinstance(obj["i"], int) or obj["i"] < 0:
                    raise ValueError("bad cursor")
                offset = obj["i"]
            except Exception:
                _log("VALIDATION_ERROR", None, workspace_id)
                return _err("VALIDATION_ERROR", "Invalid cursor.")

        rows = []
        for d in docs:
            if not isinstance(d, dict):
                continue
            if d.get("workspace_id") != workspace_id:
                continue
            # Business rule: must query only active documents and active sources
            if d.get("status") != "active":
                continue
            sid = d.get("source_id")
            if sid not in active_sources:
                continue
            if source_id is not None and sid != source_id:
                continue
            if language is not None:
                if not isinstance(language, str) or len(language.strip()) == 0:
                    _log("VALIDATION_ERROR", None, workspace_id)
                    return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.")
                if (d.get("language") or "").lower() != language.strip().lower():
                    continue
            # status filter parameter is accepted by schema, but business rule fixes to active; treat non-active as empty
            if status is not None and status != "active":
                continue

            text = (d.get("content_text") or "")
            title = (d.get("title") or "")
            if q not in (title.lower() + "\n" + text.lower()):
                # allow term-based match if query split
                if q_terms:
                    ok = True
                    combined = (title + "\n" + text).lower()
                    for t in q_terms:
                        if t not in combined:
                            ok = False
                            break
                    if not ok:
                        continue
                else:
                    continue

            sc = _score(d)
            rows.append((sc, d))

        if sort == "relevance":
            rows.sort(key=lambda x: (x[0], x[1].get("indexed_at") or "", x[1].get("id") or ""), reverse=True)
        elif sort == "indexed_at_desc":
            rows.sort(key=lambda x: (x[1].get("indexed_at") or "", x[1].get("id") or ""), reverse=True)
        else:
            rows.sort(key=lambda x: (x[1].get("indexed_at") or "", x[1].get("id") or ""))

        total = len(rows)
        page = rows[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            payload = json.dumps({"i": next_offset}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        out = []
        for sc, d in page:
            # must include canonical_url
            out.append({
                "id": d.get("id"),
                "workspace_id": d.get("workspace_id"),
                "source_id": d.get("source_id"),
                "canonical_url": d.get("canonical_url"),
                "title": d.get("title"),
                "language": d.get("language"),
                "indexed_at": d.get("indexed_at"),
                "status": d.get("status"),
                "score": sc
            })

        _log("OK", None, workspace_id)
        return {"object": "list", "data": out, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}
    except Exception as e:
        _log("FAILED", None, workspace_id if isinstance(workspace_id, str) else None)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def ref_read_url(workspace_id, url, use_cache=None, force_refresh=None, timeout_ms=None, **_extra):
    import json, os, datetime, re, time, hashlib, ipaddress
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0188000" if __import__("os").path.isdir("./environment_mix/0188000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return prefix + hashlib.sha256(f"{time.time()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")).hexdigest()[:16]

    def _log(status_code, credential_id=None, workspace_id_used=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("ref_req_"),
            "tool": "ref_read_url",
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _valid_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _canonicalize(u):
        sp = urlsplit(u)
        scheme = (sp.scheme or "").lower()
        netloc = sp.netloc
        path = sp.path or ""
        query = sp.query or ""
        # strip fragment
        fragment = ""
        # normalize host casing, remove default ports
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
        else:
            userinfo, hostport = None, netloc
        host = hostport
        port = None
        if hostport.startswith("["):
            # IPv6 literal
            if "]" in hostport:
                h = hostport[1:hostport.index("]")]
                rest = hostport[hostport.index("]") + 1:]
                host = "[" + h.lower() + "]"
                if rest.startswith(":"):
                    try:
                        port = int(rest[1:])
                    except Exception:
                        port = None
            else:
                host = hostport.lower()
        else:
            if ":" in hostport:
                h, p = hostport.rsplit(":", 1)
                host = h.lower()
                try:
                    port = int(p)
                except Exception:
                    port = None
            else:
                host = hostport.lower()
        # resolve default ports
        default_port = 80 if scheme == "http" else 443 if scheme == "https" else None
        use_port = port
        if default_port is not None and port == default_port:
            use_port = None
        net = host
        if use_port is not None:
            net = f"{host}:{use_port}"
        if userinfo:
            net = f"{userinfo}@{net}"
        return urlunsplit((scheme, net, path, query, fragment))

    def _host_is_private(host):
        h = host
        if h.startswith("[") and h.endswith("]"):
            h = h[1:-1]
        # strip possible port already removed by parsing, but be safe
        if ":" in h and not re.match(r"^[0-9a-fA-F:]+$", h):
            h = h.split(":")[0]
        # block localhost by name too
        if h.lower() in ("localhost",):
            return True
        try:
            ip = ipaddress.ip_address(h)
            # include RFC1918/loopback/link-local/ULA
            if ip.is_loopback or ip.is_private or ip.is_link_local:
                return True
            # ip.is_reserved covers some special ranges; be conservative
            if getattr(ip, "is_reserved", False):
                return True
        except Exception:
            # Not an IP literal; cannot DNS resolve offline. Only block obvious localhost-like.
            if h.lower().endswith(".localhost") or h.lower().endswith(".local"):
                return True
        # Explicit blocks requested
        try:
            ip = ipaddress.ip_address(h)
            if ip.version == 6:
                if ip == ipaddress.ip_address("::1"):
                    return True
                if ip in ipaddress.ip_network("fc00::/7"):
                    return True
        except Exception:
            pass
        return False

    def _rate_limited(workspace_id_):
        # max 60 per minute per workspace, counting attempts
        reqs = _load("read_url_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id_:
                continue
            ts = r.get("requested_at")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if t >= cutoff:
                cnt += 1
        return cnt >= 60

    def _cache_is_nonexpired(entry):
        if not isinstance(entry, dict):
            return False
        if entry.get("status") != "fresh":
            return False
        if not entry.get("markdown"):
            return False
        fetched_at = entry.get("fetched_at")
        if not isinstance(fetched_at, str) or not fetched_at.endswith("Z"):
            return False
        expires_at = entry.get("expires_at")
        if expires_at is None:
            return True
        if not isinstance(expires_at, str) or not expires_at.endswith("Z"):
            return False
        try:
            exp = datetime.datetime.fromisoformat(expires_at[:-1])
        except Exception:
            return False
        return exp >= now_dt

    try:
        if not _valid_id(r"^ref_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
            _log("VALIDATION_ERROR", None, workspace_id if isinstance(workspace_id, str) else None)
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
        if not isinstance(url, str) or len(url.strip()) < 1:
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "url must be a non-empty string.")
        u = url.strip()
        sp = urlsplit(u)
        if sp.scheme.lower() not in ("http", "https") or not sp.netloc:
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "url must be an http(s) URL with host.")
        if timeout_ms is None:
            timeout_ms = 30000
        if not isinstance(timeout_ms, int) or timeout_ms < 1000 or timeout_ms > 120000:
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "timeout_ms must be between 1000 and 120000.")
        if use_cache is None:
            use_cache = True
        if force_refresh is None:
            force_refresh = False
        if not isinstance(use_cache, bool) or not isinstance(force_refresh, bool):
            _log("VALIDATION_ERROR", None, workspace_id)
            return _err("VALIDATION_ERROR", "use_cache and force_refresh must be boolean when provided.")

        workspaces = _load("workspaces.json")
        if not any(isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") != "deleted" for w in workspaces):
            _log("NOT_FOUND", None, workspace_id)
            return _err("NOT_FOUND", "Workspace not found.")

        normalized_url = _canonicalize(u)
        nsp = urlsplit(normalized_url)
        host = nsp.hostname or ""
        if _host_is_private(host):
            # must record request with blocked
            reqs = _load("read_url_requests.json")
            if not isinstance(reqs, list):
                reqs = []
            rid = _new_id("ref_rur_")
            req_row = {
                "id": rid,
                "workspace_id": workspace_id,
                "url": u,
                "normalized_url": normalized_url,
                "status": "blocked",
                "http_status": None,
                "error_code": "ssrf_blocked",
                "error_message": "URL blocked by SSRF protection policy.",
                "served_from_cache": False,
                "cache_entry_id": None,
                "requested_at": now,
                "completed_at": now,
                "created_at": now,
                "updated_at": now
            }
            reqs.append(req_row)
            _save("read_url_requests.json", reqs)
            _log("OK", None, workspace_id)
            return {
                "request": req_row,
                "result": None
            }

        # Create request row (always)
        reqs = _load("read_url_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        rid = _new_id("ref_rur_")
        req_row = {
            "id": rid,
            "workspace_id": workspace_id,
            "url": u,
            "normalized_url": normalized_url,
            "status": "queued",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "served_from_cache": False,
            "cache_entry_id": None,
            "requested_at": now,
            "completed_at": None,
            "created_at": now,
            "updated_at": now
        }

        # Rate limit: refuse additional calls but still record attempt as failed+rate_limited
        if _rate_limited(workspace_id):
            req_row["status"] = "failed"
            req_row["error_code"] = "rate_limited"
            req_row["error_message"] = "Rate limit exceeded (60 requests/minute)."
            req_row["completed_at"] = now
            req_row["updated_at"] = now
            reqs.append(req_row)
            _save("read_url_requests.json", reqs)
            _log("RATE_LIMIT", None, workspace_id)
            return _err("RATE_LIMIT", "Rate limit exceeded.", request=req_row)

        # attempt cache reuse
        cache = _load("url_content_cache.json")
        if not isinstance(cache, list):
            cache = []
        used_entry = None
        if use_cache and not force_refresh:
            for e in cache:
                if not isinstance(e, dict):
                    continue
                if e.get("workspace_id") != workspace_id:
                    continue
                if e.get("normalized_url") != normalized_url:
                    continue
                if _cache_is_nonexpired(e):
                    used_entry = e
                    break

        if used_entry is not None:
            req_row["status"] = "succeeded"
            req_row["served_from_cache"] = True
            req_row["cache_entry_id"] = used_entry.get("id")
            req_row["completed_at"] = now
            req_row["updated_at"] = now
            reqs.append(req_row)
            _save("read_url_requests.json", reqs)
            _log("OK", None, workspace_id)
            return {
                "request": req_row,
                "cache_entry": used_entry,
                "markdown": used_entry.get("markdown"),
                "normalized_url": normalized_url,
                "final_url": used_entry.get("final_url") or used_entry.get("normalized_url")
            }

        # Offline environment: no network IO; treat as fetch failure.
        req_row["status"] = "fetching"
        req_row["updated_at"] = now
        reqs.append(req_row)
        _save("read_url_requests.json", reqs)

        # mark failed (no cache served; no fresh cache created)
        req_row["status"] = "failed"
        req_row["error_code"] = "fetch_failed"
        req_row["error_message"] = "Upstream fetch not available in offline datastore environment."
        req_row["completed_at"] = now
        req_row["updated_at"] = now

        # Persist update (mutation must have effect)
        reqs2 = _load("read_url_requests.json")
        if not isinstance(reqs2, list):
            reqs2 = []
        updated = False
        for i, r in enumerate(reqs2):
            if isinstance(r, dict) and r.get("id") == rid:
                reqs2[i] = req_row
                updated = True
                break
        if not updated:
            _log("CONFLICT", None, workspace_id)
            return _err("CONFLICT", "Failed to persist request status update.")
        _save("read_url_requests.json", reqs2)

        _log("OK", None, workspace_id)
        return {"request": req_row, "result": None}
    except Exception as e:
        _log("FAILED", None, workspace_id if isinstance(workspace_id, str) else None)
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def ref_get_current_actor(workspace_id=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0188000" if __import__("os").path.isdir("./environment_mix/0188000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return prefix + hashlib.sha256(f"{time.time()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")).hexdigest()[:16]

    def _log(status_code, credential_id=None, workspace_id_used=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("ref_req_"),
            "tool": "ref_get_current_actor",
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _valid_wsp(val):
        return isinstance(val, str) and re.match(r"^ref_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", val) is not None

    try:
        if workspace_id is not None and not _valid_wsp(workspace_id):
            _log("VALIDATION_ERROR", None, workspace_id if isinstance(workspace_id, str) else None)
            return _err("VALIDATION_ERROR", "Invalid workspace_id format.")

        # No explicit credential parameter exists; authentication is ambient.
        # Resolve a usable workspace context from datastore.
        wss = _load("workspaces.json")
        if not isinstance(wss, list):
            wss = []
        target = None
        if workspace_id is not None:
            for w in wss:
                if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") == "active":
                    target = w
                    break
            if target is None:
                _log("UNAUTHORIZED", None, workspace_id)
                return _err("UNAUTHORIZED", "No authorized active workspace context available for this request.")
        else:
            for w in wss:
                if isinstance(w, dict) and w.get("status") == "active":
                    target = w
                    break
            if target is None:
                _log("UNAUTHORIZED", None, None)
                return _err("UNAUTHORIZED", "No authorized workspace context available for this request.")

        # Compute current read_url rate usage (last 60s) for the workspace.
        reqs = _load("read_url_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != target.get("id"):
                continue
            ts = r.get("requested_at")
