        possible_files = ["request_log.json", "requests.json", "audit_log.json", "usage_logs.json", "api_requests.json"]
        for fn in possible_files:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                logs = _load(fn)
                if not isinstance(logs, list):
                    logs = []
                row = {
                    "id": None,
                    "endpoint": endpoint,
                    "status": status,
                    "workspace_id": workspace_id_used,
                    "cache_entry_id": cache_entry_id_used,
                    "timestamp": _now_iso(),
                    "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                }
                if isinstance(extra, dict):
                    row.update(extra)
                logs.append(row)
                _save(fn, logs)
                break

    t0 = time.time()
    endpoint = "ref_get_url_content_cache_entry"

    # ---- Validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^ref_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _record_attempt("VALIDATION_ERROR", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    if not isinstance(cache_entry_id, str) or not cache_entry_id:
        _record_attempt("VALIDATION_ERROR", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("VALIDATION_ERROR", "Invalid cache_entry_id.")

    # Vendor schema pattern says ref_cache_..., but real datastore uses ref_ucc_...
    # Accept both to match real service tolerance / migration.
    if not (
        re.match(r"^ref_cache_[0-9A-HJKMNP-TV-Z]{10,}$", cache_entry_id)
        or re.match(r"^ref_ucc_[0-9A-HJKMNP-TV-Z]{10,}$", cache_entry_id)
    ):
        _record_attempt("VALIDATION_ERROR", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("VALIDATION_ERROR", "Invalid cache_entry_id format.")

    # ---- Resolve workspace (ambient auth: if it exists, it's accessible) ----
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        _record_attempt("CONFLICT", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("CONFLICT", "Datastore corrupted: workspaces.json is not a list.")

    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not wsp:
        _record_attempt("NOT_FOUND", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("NOT_FOUND", "Workspace not found.")

    # ---- Fetch cache entry ----
    cache_rows = _load("url_content_cache.json")
    if not isinstance(cache_rows, list):
        _record_attempt("CONFLICT", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("CONFLICT", "Datastore corrupted: url_content_cache.json is not a list.")

    # Primary lookup: must be in the given workspace.
    entry = next(
        (r for r in cache_rows if isinstance(r, dict) and r.get("id") == cache_entry_id and r.get("workspace_id") == workspace_id),
        None,
    )

    if not entry:
        # Important: do NOT "resolve a different context" or switch workspaces; this endpoint is scoped.
        # Return NOT_FOUND, but be tolerant about vendor-id prefix drift by checking if same id exists elsewhere
        # and still refusing (prevents confusing "works in some other workspace" leaks).
        _record_attempt("NOT_FOUND", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
        return _err("NOT_FOUND", "Cache entry not found in this workspace.")

    # ---- Return stored content and metadata (do not fabricate fields) ----
    # The real API returns markdown/text plus fetch metadata.
    resp = {
        "cache_entry": entry,
    }

    _record_attempt("OK", workspace_id_used=workspace_id, cache_entry_id_used=cache_entry_id)
    return resp
